-- TAX-004: canonical ATTRIBUTE_GRAPH_V1 Skill -> Attribute membership.
begin;

on conflict (relationship_type,source_entity_id,target_entity_id) do nothing;

do $$
declare affects_count integer; uncovered_skills integer; uncovered_attributes integer; invalid_edges integer; duplicate_edges integer; belongs_count integer;
begin
  select count(*) into affects_count from public.taxonomy_relationships where relationship_type='AFFECTS' and metadata->>'graph_version'='ATTRIBUTE_GRAPH_V1';
  select count(*) into uncovered_skills from public.taxonomy_entities s where s.kind='SKILL' and s.lifecycle='ACTIVE' and not exists(select 1 from public.taxonomy_relationships r where r.relationship_type='AFFECTS' and r.source_entity_id=s.id);
  select count(*) into uncovered_attributes from public.taxonomy_entities a where a.kind='ATTRIBUTE' and a.lifecycle='ACTIVE' and not exists(select 1 from public.taxonomy_relationships r where r.relationship_type='AFFECTS' and r.target_entity_id=a.id);
  select count(*) into invalid_edges from public.taxonomy_relationships r join public.taxonomy_entities s on s.id=r.source_entity_id join public.taxonomy_entities a on a.id=r.target_entity_id where r.relationship_type='AFFECTS' and (s.kind<>'SKILL' or a.kind<>'ATTRIBUTE');
  select count(*) into duplicate_edges from (select source_entity_id,target_entity_id from public.taxonomy_relationships where relationship_type='AFFECTS' group by source_entity_id,target_entity_id having count(*)>1) duplicate_pairs;
  select count(*) into belongs_count from public.taxonomy_relationships where relationship_type='BELONGS_TO';
  if affects_count<>141 then raise exception 'ATTRIBUTE_GRAPH_V1 expected 141 edges, found %',affects_count; end if;
  if uncovered_skills<>0 then raise exception 'ATTRIBUTE_GRAPH_V1 leaves % active Skills uncovered',uncovered_skills; end if;
  if uncovered_attributes<>0 then raise exception 'ATTRIBUTE_GRAPH_V1 leaves % active Attributes uncovered',uncovered_attributes; end if;
  if invalid_edges<>0 then raise exception 'AFFECTS contains % invalid endpoint pairs',invalid_edges; end if;
  if duplicate_edges<>0 then raise exception 'AFFECTS contains % duplicate pairs',duplicate_edges; end if;
  if belongs_count<>72 then raise exception 'TAX-004 expected 72 unchanged BELONGS_TO edges, found %',belongs_count; end if;
end $$;

commit;
